<template><section ref="root" class="care-day-story" aria-label="一天的照護故事"><CareStoryScene v-for="scene in scenes" :key="scene.id" :scene="scene"><template v-if="scene.id==='07'" #progress><div class="scene-progress" data-progress-route><div class="scene-progress-route"><div><UserRoundCheck :size="44"/><span>居服員</span></div><div class="scene-progress-line"><i></i><span class="route-dot"></span></div><div><HouseHeart :size="46"/><span>家</span></div></div><ol class="scene-progress-steps"><li v-for="item in progressSteps" :key="item.label"><component :is="item.icon" :size="24"/><span>{{ item.label }}</span></li></ol></div></template><template v-if="scene.id==='08'" #ending><div class="scene-ending-cta"><p class="scene-ending-eyebrow">一直都在</p><h3>照顧的路上，<br>有人陪你一起。</h3><p>照顧不孤單，我們一直都在。</p><div class="scene-ending-actions"><router-link to="/caregivers">找居服員 <ArrowRight :size="20"/></router-link><button type="button" @click="emit('line')">不熟悉網站？請 LINE 專人協助</button></div></div></template></CareStoryScene><CareStoryProgress :items="scenes" :active="activeScene"/></section></template>
<script setup lang="ts">
import{onBeforeUnmount,onMounted,ref}from'vue';import{ArrowRight,HouseHeart,UserRoundCheck}from'@lucide/vue';import{gsap,ScrollTrigger}from'@/composables/useGsap';import CareStoryProgress from'./CareStoryProgress.vue';import CareStoryScene from'./CareStoryScene.vue';import scene01 from'@/assets/home-world/story/scene-01.webp';import scene02 from'@/assets/home-world/story/scene-02.webp';import scene03 from'@/assets/home-world/story/scene-03.webp';import scene04 from'@/assets/home-world/story/scene-04.webp';import scene05 from'@/assets/home-world/story/scene-05.webp';import scene06 from'@/assets/home-world/story/scene-06.webp';import scene07 from'@/assets/home-world/story/scene-07.webp';import scene08 from'@/assets/home-world/story/scene-08.webp';
type SceneLayout='hero'|'split'|'cinematic'|'reverse'|'detail'|'work'|'outdoor'|'ending';interface CareScene{id:string;title:string;description:string;image:string;alt:string;layout:SceneLayout;objectPosition?:string}defineProps<{progressSteps:Array<{label:string;icon:any}>}>();const emit=defineEmits<{line:[]}>();
const scenes:CareScene[]=[{id:'01',title:'今天的陪伴，從家門口開始。',description:'熟悉彼此，也準備開始今天的照顧。',image:scene01,alt:'居服員在玄關替長者整理衣領，虎斑貓好奇地在旁觀察',layout:'hero',objectPosition:'center'},{id:'02',title:'今天，需要哪一種幫忙？',description:'照顧不只是一件事，而是生活裡每天不同的需要。',image:scene02,alt:'居服員與長者在客廳喝茶聊天，虎斑貓霸佔沙發前最舒服的位置',layout:'split',objectPosition:'center'},{id:'03',title:'一起準備午餐。',description:'一餐熱騰騰的飯，也是每天的安心。',image:scene03,alt:'居服員與長者一起在廚房準備午餐，虎斑貓靠近聞香',layout:'cinematic',objectPosition:'43% center'},{id:'04',title:'一起享用午餐。',description:'一頓飯，也是一段陪伴。',image:scene04,alt:'居服員替正在用餐的長者盛菜，虎斑貓在餐桌旁探頭',layout:'reverse',objectPosition:'center'},{id:'05',title:'飯後，喝杯茶聊聊天。',description:'有些照顧，只是有人願意坐下來聽。',image:scene05,alt:'居服員與長者在客廳喝茶聊天，虎斑貓在沙發旁休息',layout:'detail',objectPosition:'38% center'},{id:'06',title:'一起整理生活。',description:'需要幫忙的地方有人接手，也保留自己能做的事。',image:scene06,alt:'居服員與長者一起摺衣服，虎斑貓守著洗衣籃',layout:'work',objectPosition:'center'},{id:'07',title:'陪奶奶走出家門。',description:'外面的世界，也有人陪你一起。',image:scene07,alt:'居服員陪拿著手杖的長者走出家門，虎斑貓停在門檻內',layout:'outdoor',objectPosition:'center'},{id:'08',title:'今天的服務結束了。',description:'照顧告一段落，安心沒有離開。',image:scene08,alt:'傍晚長者在門口向準備離開的居服員揮手，虎斑貓在牆頭目送',layout:'ending',objectPosition:'center'}];
const root=ref<HTMLElement>();const activeScene=ref(0);let context:gsap.Context|undefined;let media:gsap.MatchMedia|undefined;
onMounted(()=>{if(!root.value)return;context=gsap.context(()=>{media=gsap.matchMedia();media.add('(min-width:901px) and (prefers-reduced-motion:no-preference)',()=>{gsap.utils.toArray<HTMLElement>('.care-scene').forEach((article,index)=>{const image=article.querySelector<HTMLElement>('.care-scene__image');const copy=article.querySelector<HTMLElement>('.care-scene__copy');ScrollTrigger.create({trigger:article,start:'top 55%',end:'bottom 45%',onToggle:self=>{if(self.isActive)activeScene.value=index}});const timeline=gsap.timeline({scrollTrigger:{trigger:article,start:'top 80%',end:'bottom 20%',scrub:1}});if(index===0)timeline.fromTo(image,{scale:1.03},{scale:1,ease:'none'});else if(index===1)timeline.fromTo(image,{yPercent:2},{yPercent:-2,ease:'none'});else if(index===2)timeline.fromTo(image,{xPercent:-1},{xPercent:1,ease:'none'});else if(index===3)timeline.fromTo(image,{scale:1.02},{scale:1,ease:'none'});else if(index===4)timeline.fromTo(image,{scale:1.04},{scale:1,ease:'none'});else if(index===5)timeline.fromTo(image,{yPercent:2},{yPercent:-2,ease:'none'});else if(index===6)timeline.fromTo(image,{xPercent:2},{xPercent:-2,ease:'none'});else timeline.fromTo(image,{scale:1},{scale:1.03,ease:'none'}).fromTo(copy,{autoAlpha:.3,y:24},{autoAlpha:1,y:0},0)});gsap.fromTo('.scene-progress-line i',{scaleX:0},{scaleX:1,ease:'none',scrollTrigger:{trigger:'#care-scene-07',start:'top 70%',end:'bottom 35%',scrub:1}});gsap.fromTo('.scene-progress-line .route-dot',{left:'0%'},{left:'100%',ease:'none',scrollTrigger:{trigger:'#care-scene-07',start:'top 70%',end:'bottom 35%',scrub:1}})});media.add('(max-width:900px)',()=>gsap.utils.toArray<HTMLElement>('.care-scene').forEach((article,index)=>ScrollTrigger.create({trigger:article,start:'top 55%',end:'bottom 45%',onToggle:self=>{if(self.isActive)activeScene.value=index}})))},root.value);ScrollTrigger.refresh()});onBeforeUnmount(()=>{media?.revert();context?.revert()});
</script>
<style scoped>.care-day-story{position:relative;background:#2d2019}.scene-progress{margin-top:32px;color:#fff}.scene-progress-route{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:20px}.scene-progress-route>div:not(.scene-progress-line){display:grid;place-items:center;gap:4px;font-weight:700}.scene-progress-line{position:relative;height:4px;background:rgba(255,255,255,.4)}.scene-progress-line i{position:absolute;inset:0;background:#fff;transform-origin:left}.route-dot{position:absolute;left:0;top:50%;width:16px;height:16px;background:#fff;border-radius:50%;transform:translate(-50%,-50%)}.scene-progress-steps{display:flex;justify-content:space-between;gap:12px;margin:22px 0 0;padding:0;list-style:none}.scene-progress-steps li{display:flex;align-items:center;gap:6px;color:#fff;font-size:.85rem}.scene-ending-cta{margin-top:34px}.scene-ending-eyebrow{font-size:.82rem;font-weight:800;letter-spacing:.18em}.scene-ending-cta h3{margin:10px 0;font-size:clamp(1.8rem,3.2vw,3.4rem);line-height:1.15}.scene-ending-actions{display:flex;align-items:center;gap:14px;margin-top:26px}.scene-ending-actions a,.scene-ending-actions button{min-height:50px;display:inline-flex;align-items:center;justify-content:center;gap:7px;padding:0 22px;border-radius:999px;color:#fff;text-decoration:none;font:inherit;font-weight:700;cursor:pointer}.scene-ending-actions a{background:#c85618;border:1px solid #c85618}.scene-ending-actions button{background:transparent;border:1px solid #fff}@media(max-width:900px){.scene-progress{margin-top:24px}.scene-progress-route svg{width:34px}.scene-progress-steps li{display:grid;place-items:center;text-align:center;font-size:.68rem}.scene-progress-steps svg{width:18px}.scene-ending-cta{margin-top:24px}.scene-ending-actions{align-items:stretch;flex-direction:column}.scene-ending-actions a,.scene-ending-actions button{width:100%}}</style>
